import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = '/var/lib/app/users.db'
app.config['HMAC_SECRET'] = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Verify HMAC signature of the key
        parts = api_key.split(':')
        if len(parts) != 2:
            return jsonify({'error': 'Invalid key format'}), 401
        key_id, signature = parts
        expected = hmac.new(app.config['HMAC_SECRET'].encode(),
                           key_id.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(signature, expected):
            return jsonify({'error': 'Invalid API key'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@require_api_key
def search_users():
    """Search users by various fields. Supports flexible filtering."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'department', 'role', 'status']
    if field not in allowed_fields:
        return jsonify({'error': f'Invalid field. Allowed: {allowed_fields}'}), 400

    # Build query - field is validated above so safe to interpolate
    # Value uses LIKE for flexible matching
    query = f"SELECT id, username, email, department, role, status FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
@require_api_key
def get_user(user_id):
    """Get user by ID - uses parameterized query."""
    db = get_db()
    cursor = db.execute('SELECT id, username, email, department, role, status FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users/<int:user_id>/notes', methods=['POST'])
@require_api_key
def add_note(user_id):
    """Add a note to a user record."""
    data = request.get_json()
    if not data or 'note' not in data:
        return jsonify({'error': 'Missing note field'}), 400

    note = data['note']
    author = data.get('author', 'system')

    # Truncate note to prevent abuse
    note = note[:500]
    author = author[:50]

    db = get_db()
    db.execute('INSERT INTO notes (user_id, note, author) VALUES (?, ?, ?)',
               (user_id, note, author))
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
